// DATA was recorded from Node v24.21.0 by running the same operations; every table below is a
// measured result, not an expectation derived from the implementation. Strings are stored as
// space separated hex UTF-16 code units so lone surrogates survive.

const units = (s: string) =>
  Array.from({ length: s.length }, (_, i) => s.charCodeAt(i).toString(16)).join(" ");
const fromUnits = (h: string) =>
  h === "" ? "" : h.split(" ").map((x) => String.fromCharCode(parseInt(x, 16))).join("");
const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");
const code = (f: () => unknown) => {
  try {
    f();
    return "ok";
  } catch (e: any) {
    return `${e.code}|${e.name}`;
  }
};
const decodeArg = (a: any) => (a === "@u" ? undefined : typeof a === "string" && a.startsWith("@") ? Number(a.slice(1)) : a);

const all = Buffer.alloc(256);
for (let i = 0; i < 256; i++) all[i] = i;

describe("toString over the full 0x00-0xFF byte table", () => {
  for (const [enc, expected] of Object.entries<string>(DATA.allToString)) {
    it(`matches Node for ${enc}`, () => {
      expect(units(all.toString(enc as BufferEncoding))).toBe(expected);
    });
  }

  it("latin1 and binary map each byte to the same code point", () => {
    for (const enc of ["latin1", "binary"] as const) {
      for (let b = 0; b < 256; b++) {
        const s = Buffer.from([b]).toString(enc);
        expect(s.length).toBe(1);
        expect(s.charCodeAt(0)).toBe(b);
      }
      expect(all.toString(enc).length).toBe(256);
    }
  });

  it("ascii clears the high bit of each byte", () => {
    for (let b = 0; b < 256; b++) {
      expect(Buffer.from([b]).toString("ascii").charCodeAt(0)).toBe(b & 0x7f);
    }
  });

  it("utf8 replaces invalid bytes and keeps valid ones", () => {
    expect(Buffer.from([0x68, 0xc3, 0xa9, 0xff, 0x41]).toString("utf8")).toBe("h\u00e9\ufffdA");
    for (let b = 0x80; b < 256; b++) {
      expect(Buffer.from([b]).toString("utf8")).toBe("\ufffd");
    }
  });

  for (const [enc, expected] of Object.entries<string>(DATA.oddToString)) {
    it(`odd length and surrogate bytes match Node for ${enc}`, () => {
      expect(units(Buffer.from([0x00, 0xd8, 0x41, 0xff, 0xdc]).toString(enc as BufferEncoding))).toBe(expected);
    });
  }

  it("random byte strings match Node for every encoding", () => {
    for (const row of DATA.randBytes) {
      const b = Buffer.from(row.b, "hex");
      for (const enc of ["base64", "base64url", "hex", "latin1", "ascii", "ucs2", "utf8"] as const) {
        expect(units(b.toString(enc))).toBe(row[enc]);
      }
    }
  });
});

describe("Buffer.from(string, encoding)", () => {
  for (const enc of Object.keys(DATA.fromStrings)) {
    for (const [name, expected] of Object.entries<string>(DATA.fromStrings[enc])) {
      it(`${enc} ${name}`, () => {
        expect(hex(Buffer.from(fromUnits(DATA.strs[name]), enc as BufferEncoding))).toBe(expected);
      });
    }
  }

  it("latin1 keeps only the low byte of every code unit", () => {
    expect([...Buffer.from("\u00e9\u0100\u0141\u{1f600}", "latin1")]).toEqual([0xe9, 0x00, 0x41, 0x3d, 0x00]);
  });

  it("latin1, binary, hex, base64, base64url and ucs2 round-trip the full byte table", () => {
    for (const enc of ["latin1", "binary", "hex", "base64", "base64url", "ucs2"] as const) {
      expect(Buffer.from(all.toString(enc), enc).equals(all)).toBe(true);
    }
  });

  it("random strings match Node for decoding encodings and byteLength", () => {
    for (const row of DATA.fuzz) {
      const s = fromUnits(row.s);
      for (const enc of ["base64", "base64url", "hex", "latin1", "ucs2", "utf8"] as const) {
        expect(hex(Buffer.from(s, enc))).toBe(row[enc][0]);
        expect(Buffer.byteLength(s, enc)).toBe(row[enc][1]);
      }
    }
  });

  it("rejects unknown encodings with ERR_UNKNOWN_ENCODING", () => {
    expect(() => Buffer.from("a", "bogus" as any)).toThrow(/Unknown encoding: bogus/);
  });

  it("ignores an encoding for non-string sources", () => {
    expect([...Buffer.from(new Uint8Array([1, 2, 3]), "hex" as any)]).toEqual([1, 2, 3]);
    expect([...Buffer.from(Buffer.from("ab"), "binary" as any)]).toEqual([0x61, 0x62]);
  });
});

describe("Buffer.byteLength", () => {
  for (const [enc, row] of Object.entries<Record<string, number>>(DATA.byteLength)) {
    for (const [name, expected] of Object.entries(row)) {
      it(`${enc} ${name}`, () => {
        const e = enc === "undefined" ? undefined : enc === "null" ? null : enc;
        expect(Buffer.byteLength(fromUnits(DATA.strs[name]), e as any)).toBe(expected);
      });
    }
  }

  it("returns the view length for buffers regardless of encoding", () => {
    expect(Buffer.byteLength(Buffer.from([1, 2, 3]), "hex" as any)).toBe(3);
  });
});

describe("toString(encoding, start, end)", () => {
  const b8 = Buffer.from([0x68, 0xe9, 0xff, 0x80, 0x41, 0x00, 0xc8, 0x7f]);

  DATA.slices.forEach((row: any, i: number) => {
    it(`#${i} ${row.e} (${row.a.map(String).join(", ")})`, () => {
      const args = row.a.map(decodeArg);
      expect(units((b8 as any).toString(row.e, ...args))).toBe(row.r);
    });
  });

  DATA.sliceNoEnc.forEach((expected: string, i: number) => {
    it(`default encoding #${i}`, () => {
      const args = (DATA.slices[i].a as any[]).slice(0, 2).map(decodeArg);
      expect(units((b8 as any).toString(undefined, ...args))).toBe(expected);
    });
  });

  it("does not panic when start is past end", () => {
    expect(b8.toString("latin1", 5, 2)).toBe("");
    expect(b8.toString("utf8", 3, 1)).toBe("");
  });

  it("slices views with a non-zero byteOffset", () => {
    const view = Buffer.from([0, 1, 0xe9, 0xff, 4]).subarray(2, 4);
    expect(view.toString("latin1")).toBe("\u00e9\u00ff");
    expect(view.toString("latin1", 1)).toBe("\u00ff");
  });
});

describe("error behaviour", () => {
  const b8 = Buffer.from([0x68, 0xe9, 0xff, 0x80, 0x41, 0x00, 0xc8, 0x7f]);
  const ops: Record<string, () => unknown> = {
    "toString bogus": () => b8.toString("bogus" as any),
    "toString empty": () => b8.toString(""),
    "toString null": () => b8.toString(null as any),
    "toString 5": () => b8.toString(5 as any),
    "toString bogus past end": () => b8.toString("bogus" as any, 99),
    "toString bogus empty range": () => b8.toString("bogus" as any, 3, 3),
    "from bogus": () => Buffer.from("a", "bogus" as any),
    "alloc bogus": () => Buffer.alloc(3, "a", "bogus" as any),
    "write bogus": () => b8.write("a", "bogus" as any),
    "alloc hex bad": () => Buffer.alloc(3, "zz", "hex"),
    "write non-string": () => b8.write(5 as any),
    "write offset range": () => b8.write("a", 9),
    "write offset neg": () => b8.write("a", -1),
    "write length range": () => b8.write("a", 1, 20),
    "write offset frac": () => b8.write("a", 1.5),
    "write offset NaN": () => b8.write("a", NaN),
  };
  for (const [name, expected] of DATA.errors as [string, string][]) {
    it(`${name} -> ${expected}`, () => {
      expect(code(ops[name])).toBe(expected);
    });
  }

  it("messages follow Node", () => {
    expect(() => b8.write("a", 9)).toThrow('The value of "offset" is out of range. It must be >= 0 && <= 8. Received 9');
    expect(() => b8.write("a", 1.5)).toThrow('The value of "offset" is out of range. It must be an integer. Received 1.5');
    expect(() => b8.toString("bogus" as any)).toThrow("Unknown encoding: bogus");
  });
});

describe("Buffer.isEncoding", () => {
  for (const [enc, expected] of DATA.isEncoding as [string, boolean][]) {
    it(JSON.stringify(enc), () => {
      expect(Buffer.isEncoding(enc)).toBe(expected);
    });
  }
  it("is false for non-strings", () => {
    expect([undefined, null, 5, {}].map((v) => Buffer.isEncoding(v as any))).toEqual(DATA.isEncodingNon);
  });
});

describe("buf.write(string, offset, length, encoding)", () => {
  (DATA.writes as [any[], string][]).forEach(([args, expected], i) => {
    it(`#${i} ${JSON.stringify(args.map((a) => (typeof a === "string" ? a.replace(/[^\x20-\x7e]/g, "?") : a)))}`, () => {
      const target = Buffer.alloc(8, 0x2e);
      const callArgs = args.map((a) => (a === "err" ? undefined : decodeArg(a)));
      let actual: string;
      try {
        actual = `${(target as any).write(...callArgs)}:${hex(target)}`;
      } catch (e: any) {
        actual = `${e.code}|${e.name}`;
      }
      expect(actual).toBe(expected);
    });
  });

  it("writes relative to the view when the buffer is a subarray", () => {
    const parent = Buffer.alloc(10, 0x2e);
    const view = parent.subarray(3, 9);
    view.write("\u00e9z", 1, "latin1");
    expect(hex(parent)).toBe(DATA.subWrite[0]);
    expect(view.write("QQ", 4, "latin1")).toBe(DATA.subWrite[1]);
  });
});

describe("Buffer.alloc(size, string, encoding)", () => {
  for (const [enc, rows] of Object.entries<string[]>(DATA.alloc)) {
    const cases: [string, number][] = [["\u00e9\u00ff", 5], ["abcd", 7], ["", 3]];
    cases.forEach(([fill, n], i) => {
      it(`${enc} fill ${JSON.stringify(fill)} x${n}`, () => {
        let actual: string;
        try {
          actual = hex(Buffer.alloc(n, fill, enc as BufferEncoding));
        } catch (e: any) {
          actual = `${e.code}|${e.name}`;
        }
        expect(actual).toBe(rows[i]);
      });
    });
  }
  it("hex fill", () => {
    expect(hex(Buffer.alloc(5, "ab01", "hex"))).toBe(DATA.allocHexOk);
  });
});

describe("lenient hex and base64 decoding", () => {
  const cases: [string, BufferEncoding, number[]][] = [
    ["0aFFg1", "hex", [10, 255]],
    ["abc", "hex", [0xab]],
    ["A", "hex", []],
    ["AQID/+-_=", "base64", [1, 2, 3, 255, 239, 191]],
    ["AQ", "base64", [1]],
    ["A", "base64", []],
    ["AQ==AQ==", "base64", [1]],
    ["A Q\nI D", "base64", [1, 2, 3]],
    ["AQI=", "base64url", [1, 2]],
    ["--__", "base64url", [251, 239, 255]],
    ["YQ=", "base64", [97]],
    ["=YQ", "base64", []],
    ["Y===", "base64", []],
    ["YWJjZA===", "base64", [97, 98, 99, 100]],
  ];
  for (const [input, enc, expected] of cases) {
    it(`${JSON.stringify(input)} as ${enc}`, () => {
      expect([...Buffer.from(input, enc)]).toEqual(expected);
    });
  }
});
